  0: { s: '0', c: '1' }, 30: { s: '1/2', c: '√3/2' }, 45: { s: '√2/2', c: '√2/2' },
  60: { s: '√3/2', c: '1/2' }, 90: { s: '1', c: '0' }, 120: { s: '√3/2', c: '-1/2' },
  135: { s: '√2/2', c: '-√2/2' }, 150: { s: '1/2', c: '-√3/2' }, 180: { s: '0', c: '-1' },
