    joyRef.current = { x: (dx / m) * 100, y: (-dy / m) * 100 }; // 가장자리(반지름 1)로 정규화
  };
  const dragLevel = (e) => {
    const r = levelRef.current.getBoundingClientRect();
    const dx = (e.clientX - r.left) - r.width / 2;
    const dy = (e.clientY - r.top) - r.height / 2;
    tiltRef.current = {
      roll: Math.max(-60, Math.min(60, (dx / (r.width / 2)) * 45)),
      pitch: Math.max(-30, Math.min(30, (-dy / (r.height / 2)) * 25)),
    };
  };
  const withDrag = (handler) => (e) => {
    handler(e);
    const move = (ev) => handler(ev);
    const up = () => { window.removeEventListener('pointermove', move); window.removeEventListener('pointerup', up); };
    window.addEventListener('pointermove', move); window.addEventListener('pointerup', up);
  };

  const reset = () => {
    rateRef.current = 0;
    joyRef.current = { x: 100, y: 0 };
    tiltRef.current = { roll: 0, pitch: 0 };
    setNums((n) => ({ ...n, rate: '0.0', dir: '거의 정지' }));
  };

  return (
    <div className="min-h-full bg-gradient-to-b from-slate-50 to-slate-100 p-6">
      <div className="max-w-6xl mx-auto">
        {/* 헤더 */}
        <div className="flex items-center justify-between mb-5 flex-wrap gap-3">
          <div>
            <h1 className="text-2xl font-bold text-slate-900">MODI 수학 대시보드</h1>
            <p className="text-sm text-slate-500 mt-1">센서를 움직여 삼각함수 · 미분(변화율) · 기울기를 눈으로 확인해요</p>
          </div>
          <button onClick={reset} className="px-4 py-2 rounded-xl bg-slate-900 text-white text-sm font-semibold hover:bg-slate-700 transition-colors">
            초기화
          </button>
        </div>

        {!connected && (
          <div className="mb-5 text-sm text-indigo-700 bg-indigo-50 border border-indigo-100 rounded-xl px-4 py-2.5">
            💡 하드웨어가 없어도 괜찮아요 — <b>원의 점</b>과 <b>수평의</b>를 마우스로 드래그하고, <b>거리 슬라이더</b>를 움직여 직접 체험해 보세요.
          </div>
        )}

        <div className="grid grid-cols-1 lg:grid-cols-2 gap-5">
          {/* 조이스틱 → 삼각함수 */}
          <Card title="조이스틱 → 삼각함수" badge="단위원" accent={COLOR.angle}>
            <div className="flex justify-center cursor-pointer select-none" onPointerDown={withDrag(dragCircle)}>
              <canvas ref={circleRef} />
            </div>
            <div className="mt-2">
              <canvas ref={waveRef} className="w-full" />
              <Legend items={[{ label: 'cos θ', color: COLOR.cos }, { label: 'sin θ', color: COLOR.sin }]} />
            </div>
            <div className="mt-3 grid grid-cols-2 gap-x-5">
              <div>
                <StatRow label="각도 θ" value={nums.deg} unit="°" color={COLOR.angle} />
                <StatRow label="라디안" value={nums.rad} unit="rad" color={COLOR.angle} />
                <StatRow label="tan θ" value={nums.tan} unit="" color={COLOR.tan} />
              </div>
              <div>
                <StatRow label="cos θ (가로)" value={nums.cos} unit="" color={COLOR.cos} />
                <StatRow label="sin θ (세로)" value={nums.sin} unit="" color={COLOR.sin} />
                <StatRow label="sin²+cos²" value={nums.identity} unit="" color="#0f172a" />
              </div>
            </div>
            {nums.special ? (
              <div className="mt-2 text-xs font-semibold text-amber-700 bg-amber-50 rounded-lg px-3 py-1.5 text-center">{nums.special}</div>
            ) : null}
            <ConceptNote>
              반지름 1인 원 위 점의 <b style={{ color: COLOR.cos }}>가로 좌표가 cos</b>, <b style={{ color: COLOR.sin }}>세로 좌표가 sin</b>이에요.
              아래 파형은 각도가 커질 때 sin·cos가 어떻게 물결치는지 보여줘요. 또 <b>sin²+cos²은 항상 1</b>이죠(피타고라스 항등식).
            </ConceptNote>
          </Card>

          {/* IMU → 기울기 */}
          <Card title="IMU → 기울기 (수평의)" badge="각도 측정" accent={COLOR.roll}>
            <div className="flex justify-center h-[240px] items-center cursor-pointer select-none" onPointerDown={withDrag(dragLevel)}>
              <canvas ref={levelRef} />
            </div>
            <div className="mt-3 grid grid-cols-3 gap-x-4">
              <StatRow label="Roll" value={nums.roll} unit="°" color={COLOR.roll} />
              <StatRow label="Pitch" value={nums.pitch} unit="°" color={COLOR.pitch} />
              <StatRow label="전체 기울기" value={nums.tilt} unit="°" color="#0f172a" />
            </div>
            <ConceptNote>
              모듈을 좌우로 기울이면 <b style={{ color: COLOR.roll }}>Roll</b>로 수평선이 회전하고, 앞뒤로 기울이면 <b style={{ color: COLOR.pitch }}>Pitch</b>로 위아래로 움직여요.
              두 각을 직각삼각형의 두 변으로 보면 전체 기울기 = √(Roll²+Pitch²) 예요.
            </ConceptNote>
          </Card>
        </div>

        {/* 거리센서 → 변화율 (전체 너비) */}
        <div className="mt-5">
          <Card title="거리센서 → 변화율 (미분)" badge="순간 변화율" accent={COLOR.rate}>
            <div className="flex items-center justify-between mb-2">
              <Legend items={[{ label: '거리 f(t)', color: COLOR.dist }, { label: "변화율 f '(t)", color: COLOR.rate }]} />
              <span className="text-sm font-semibold" style={{ color: parseFloat(nums.rate) > 1.5 ? COLOR.dist : parseFloat(nums.rate) < -1.5 ? COLOR.rate : '#64748b' }}>
                {nums.dir}
              </span>
            </div>
            <div className="w-full" style={{ height: 240 }}>
              <canvas ref={chartCanvasRef} />
            </div>
            <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mt-3 items-start">
              <div className="md:col-span-1">
                <StatRow label="현재 거리" value={nums.dist} unit="cm" color={COLOR.dist} big />
                <StatRow label="변화율(속도)" value={nums.rate} unit="cm/s" color={COLOR.rate} big />
              </div>
              {!connected && (
                <label className="md:col-span-1 text-xs text-slate-500 flex flex-col gap-1.5">
                  거리 직접 조절 (데모)
                  <input type="range" min="2" max="40" defaultValue="20" step="0.5"
                    onInput={(e) => { distRef.current = parseFloat(e.target.value); }}
                    className="w-full accent-emerald-600" />
                </label>
              )}
              <ConceptNote>
                <b>변화율 = (거리 변화) ÷ (시간 변화)</b> — 그래프 선이 가파를수록 변화율이 커져요.
                초록 곡선이 <b>함수 f(t)</b>, 주황 점선이 그 <b>기울기 = 도함수 f '(t)</b>예요. 거리가 가장 클 때(꼭대기) 변화율은 0을 지나죠.
              </ConceptNote>
            </div>
          </Card>
        </div>
      </div>
    </div>
  );
}

export default App;
